from build_engine3 import *

head=[
step('entry','Confirm head-removal access','Start with the engine supported and cold, coolant drained, radiator hose and coolant-temperature coupler detached, throttle body and exhaust detached, upper engine bracket removed and cams/tensioner already removed. Secure the chain. Keep oil-passage plugs, studs and ground terminal installed for this bounded operation.',[222,223],'Named access completed; chain secured; plugs/studs/terminal undisturbed.',True,True),
step('loosen','Release the head in removal order','Use the removal-order diagram, which is different from the installation diagram. Loosen the twoM6x45 and fourM10x129 head bolts half a turn each per pass, positions1 through6, until all are loose. Then remove bolts/washers and lift the head without letting the chain fall.',[223,224],'Removal order and six bolts/washers accounted for.',True,True),
step('gasket','Remove head sealing parts','Remove the intake-side chain guide and old head gasket; retain both dowels. Check the guide for damage/wear and replace if defective. Keep the cylinder and piston supported; their service is a separate operation at this point.',[223,224,225],'Guide, gasket and dowels accounted for.',True,True),
step('inspect','Inspect the head before choosing reuse','Clean carbon with a rounded scraper that cannot score the chamber or plug threads. Clear coolant-passage deposits. Check for damage/scratches; a replaced head also requires new valves. Measure warpage with straightedge and feeler gauge across the illustrated directions; limit0.05mm. Record all directions and the reuse/repair decision.',[224],'Head condition and warpage readings saved.',True,True),
step('repair','Complete required head or cylinder work before refit','The retained-head path requires satisfactory head/valve inspection. If head repair, valve/guide replacement or cylinder/piston service is needed, complete and document that work before proceeding. OEM describes400–600-grit figure-eight resurfacing on a surface plate, rotating the head for even removal, but gives no maximum material-removal depth here; do not invent a skim allowance.',[224,231,232],'Head service disposition recorded; required repairs complete, or explicitly not needed.'),
step('seat','Install the new head gasket and head','Pull the chain upward while fitting the intake-side guide, both dowels, new gasket and head. Match the gasket orientation and openings to the illustration. Keep debris out of the cylinder and chain cavity.',[224,225],'New gasket orientation, dowels and chain guide verified.',True,True),
step('prepare-bolts','Prepare the four main head bolts','Clean main-bolt threads/contact faces, both washer faces, head contact surfaces and crankcase threads. Apply molybdenum-disulfide grease to main-bolt threads/contact faces and both washer faces. Install main bolts/washers at positions1–4 in the installation diagram and seat lightly.',[225],'Clean surfaces and all specified grease locations recorded.',True,True),
step('first','Perform the first tightening stage','Follow installation positions1–4, tightening evenly in two or three stages until all four reach36Nm. Keep the installation order visible; do not substitute the removal numbering.',[225],'Each main bolt36Nm in order recorded.',True,True),
step('second-one','Retighten only main bolt1','Remove only bolt1 without loosening another bolt. Reapply molybdenum-disulfide grease to its threads/contact face and both washer faces, reinstall and tighten18Nm. Mark bolt/head as illustrated, then rotate bolt1 another90degrees. Finish this bolt before loosening bolt2.',[225,226],'Bolt1 removed/regreased/18Nm/+90degrees recorded.',True,True),
step('second-rest','Repeat one bolt at a time','Perform the same remove, regrease,18Nm and90degree sequence for bolt2, then3, then4. Completely finish one before loosening the next. Record each bolt separately.',[225,226],'Bolts2,3,4 each18Nm/+90degrees after individual regrease recorded.',True,True),
step('final-angle','Apply the final angle','In installation order1–4, turn each main head bolt an additional60degrees. Record each final angle separately; this is not a single36Nm-plus-angle shortcut.',[226],'Final60degrees for all four bolts recorded.',True,True),
step('small','Secure the two small head bolts','Install and tighten the two small head bolts at positions5 and6 to12Nm with LOCTITE locking agent. The manual does not name a grade. Verify all six completed fasteners and leave cams/tensioner installation for its next operation.',[225,226],'Small bolts12Nm with locking agent; all six stages complete.',True,True)]
procedure('head-remove-refit-bench-v1','Remove and refit the cylinder head',head,['Engine-access and cam-removal states listed in the first step are already complete.'],['Cylinder head sealed and torqued; cam/tensioner installation and external engine closure still required.'],['Calibrated torque wrench, angle measurement tool and marking pen','Straightedge, feeler gauge, rounded scraper','Clean chain-retaining wire'],['New exact head gasket','Molybdenum-disulfide grease','LOCTITE locking agent, grade unspecified'],['Cam/tensioner removal and installation','Unspecified machining allowance','Head valve repair is a separately recorded dependency'],['engine','cylinder_head'])

piston=[
step('entry','Confirm open-head access','Start with the cylinder head removed and timing chain retained. Remove the cylinder bolt and lift the cylinder while guiding the chain through its cavity. Retain both dowels and remove the old base gasket.',[235],'Cylinder, two dowels and old gasket accounted for.',True,True),
step('pin-remove','Remove the piston without losing a clip','Cover the crankcase opening before removing the clips. Deburr the clip groove and pin-bore area before sliding out the pin. If still tight, use puller90890-01304/YU-01304; never hammer the pin. Lift off the piston, keeping debris and clips out of the engine.',[235,236],'Piston removed; both clips accounted for; case protected.',True,True),
step('rings-remove','Remove and identify the rings','Open a ring gap with your fingers and lift the opposite side over the crown as illustrated. Remove top, second and oil-ring components into a labeled tray. Clean ring grooves and rings before measuring.',[236,237],'All ring components identified; grooves clean.',True,True),
step('bore','Inspect and measure the cylinder','Check piston and cylinder walls for vertical scratches; damaged walls require cylinder replacement with piston/rings as a set. Measure side-to-side and front-to-back at each of three illustrated heights. RecordD1–D6 and use their maximum as boreC. Standard97.000–97.010mm; wear limit97.060mm.',[236],'D1–D6, maximumC and wall condition saved.',True,True),
step('piston-size','Measure piston and actual fit','Measure piston diameter with a micrometer9.0mm above the skirt bottom at the illustrated axis; standard96.955–96.970mm. Compute actual clearance=C minus measured piston diameter. OEM separately states standard0.010–0.045mm and limit0.15mm. Record the actual subtraction; individually acceptable part diameters do not automatically prove an acceptable pair.',[236,237],'Piston diameter,9mm datum and calculated fit saved.',True,True),
step('side-gap','Measure ring side clearances','With carbon removed, measure top and second ring side clearance in the piston grooves. Top standard0.015–0.065mm, limit0.120mm; second standard0.020–0.060mm, limit0.100mm. An out-of-spec result requires piston/rings as a set.',[237],'Top and second side-clearance values recorded.',True,True),
step('end-gap','Measure ring end gaps','Place each compression ring near the cylinder bottom and square it with the piston crown. Measure its gap: top limit0.55mm, second limit0.85mm. These are wear limits, not new-ring filing targets. Do not measure the oil expander as a rail; excessive oil-rail gap calls for the oil-ring set, with no numerical rail limit supplied here.',[237,238],'Top/second end gaps and oil-ring assessment saved.',True,True),
step('pin-check','Inspect pin and pin bore','Replace a blue-discolored or grooved pin and investigate lubrication. Measure pin outside diameter: minimum wear limit17.981mm. Measure piston pin-bore inside diameter: maximum limit18.045mm. Replace the defective pin or piston as specified.',[238],'PinOD, boreID and lubrication-related condition saved.',True,True),
step('parts','Confirm the rebuild parts and fit','Record reuse or exact stock replacement decisions for every failed check. Where cylinder/piston/clearance is out of specification, follow OEM set-replacement requirements. Confirm the chosen actual piston/cylinder pair satisfies the required fit; do not accept it merely because both individual dimensions fall within their separate ranges. This guide excludes rebore/replate and aftermarket ring filing.',[236,237,238],'Final installed parts and measured-fit decision documented.'),
step('rings-install','Install the ring set','Fit oil expander, lower oil rail, upper oil rail, second ring and top ring in that order. Face any manufacturer marks/numbers upward. Keep the expander correctly seated rather than overlapping its ends.',[238],'Ring order and upward marks verified.',True,True),
step('piston-install','Install piston, pin and new clips','Oil the piston and pin. Face the piston mark toward the exhaust, which is the REAR on this engine. Cover the case opening while fitting both new clips. Seat them fully; neither clip end belongs at the piston cutout.',[235,238,239],'Rear-facing mark and two new fully seated clips recorded.',True,True),
step('clock','Set the exact ring-gap positions','Oil piston, rings and cylinder. Set all five gaps from the source diagram: top(a),second(b),upper rail(c),expander(d),lower rail(e), preserving its15degree offsets and reference orientation. Keep the drawing visible; a generic120degree arrangement is not this procedure.',[239],'All five labeled gap locations checked against diagram.',True,True),
step('cylinder-install','Refit cylinder and new base gasket','Fit the new base gasket and both dowels. Compress the rings by hand while lowering the cylinder with the other hand. Pass the chain and exhaust-side guide through their cavity. Tighten the cylinder bolt10Nm. Account for protective cloths before head installation.',[235,239],'New gasket, two dowels, chain/guide passage and10Nm recorded.',True,True)]
procedure('cylinder-piston-bench-v1','Inspect and rebuild the cylinder and piston',piston,['Head removed, chain retained, crankcase protected.'],['Piston/rings/cylinder installed with new base gasket; head installation remains.'],['Cylinder bore gauge and suitable micrometers','Feeler gauges, piston-pin puller90890-01304/YU-01304','Torque wrench accurate at10Nm; clean case-protection cloths'],['New base gasket and two new piston-pin clips','Exact stock replacement piston/rings/cylinder/pin as assessment requires','Engine oil'],['Rebore/replate','Aftermarket pistons or ring-gap filing','Standard ring end-gap target is not supplied by this source'],['engine','piston','cylinder'])

valves=[
step('entry','Identify the head and valve positions','Start with the head removed and cams out. This route inspects and reseals the original serviceable valves; valve/guide replacement and seat machining must be separately resolved if inspection finds a fault. Keep the two intake and two exhaust sets labeled.',[227,228,229],'Head-on-bench state and four valve locations recorded.',True,True),
step('lifters','Remove lifters and pads','Protect the chain opening and lift each lifter/pad with the14mm valve lapper90890-04101/YM-A8998. Store each in its original valve position, recording pad identity.',[229],'Four lifters/pads labeled and retained.',True,True),
step('sealing','Check the seats before disassembly','With the valves still retained by their springs, put clean solvent in the intake/exhaust ports as shown; OEM mentions kerosene for this check. Look for leakage past each valve seat. Record each result and remove the solvent before continuing.',[229],'Four separate sealing observations saved.',True,True),
step('strip','Remove the four valve assemblies','Using compressor90890-04200/YM-04019 with22mm adapter90890-04108/YM-04108, compress each spring and remove its two cotters. Release the compressor in control, then remove retainer, spring, valve, old stem seal and spring seat. Retain original positions.',[229,230],'Eight cotters, four each retainers/springs/valves/seats accounted for; old seals discarded.',True,True),
step('guide-check','Measure stem-to-guide clearance','Measure each guideID and matching stemOD at the illustrated measurement surfaces; subtract stemOD from guideID. Intake clearance limit0.080mm, exhaust0.100mm. Record all eight dimensions and four calculations. An out-of-limit pair requires guide replacement before this head can return.',[230],'Each guideID, stemOD and calculated clearance saved.',True,True),
step('valve-check','Inspect valves and measure runout','Remove deposits without damaging faces/seats. Inspect face condition and stem ends; a mushroomed tip requires replacement. Measure stem runout on the illustrated supports, limit0.020mm. New valves require new guides; every removed valve requires a new stem seal. Do not grind or lap the original titanium valves on this reuse route.',[231,232],'Four runouts and face/stem assessments saved.',True,True),
step('seat-check','Measure contact width','Inspect seats for pitting/wear. Apply blue layout fluid to each valve face, insert its original valve and press it onto the seat to make a clean contact impression. Measure the wiped contact band; intake/exhaust width limit1.5mm. Seat damage or excessive width requires the source-directed head repair/replacement route before assembly.',[231],'Four contact widths and seat conditions recorded.',True,True),
step('spring-check','Check springs and lifters','Measure spring free lengths: intake limit36.65mm, exhaust37.34mm; replace an out-of-limit spring. Inspect lifters for damage/scratches; source requires lifters and head replacement for this damage. Record the result for every part.',[232,233],'Four spring lengths and lifter conditions saved.',True,True),
step('disposition','Confirm that the retained-valve route is valid','Proceed only when original valves/guides/seats are serviceable and no lapping or guide replacement is needed; record any new stock spring used. If repair is needed, preserve the open-head state and take the reviewed repair specification to the head-service operation. A valve used for lapping must never be installed for running, and any new valve requires the documented guide work.',[230,231,232],'Retained-valve eligibility or unresolved repair recorded; no failed part carried forward.'),
step('assemble','Install seats, new seals and original valves','Clean the stem ends. Lubricate stems and new stem seals with molybdenum-disulfide oil. Return each spring seat, new seal, original valve, spring and retainer to its recorded position. Spring coils with the larger pitch face upward.',[233],'Four new seals and original positions/spring direction recorded.',True,True),
step('cotters','Secure each spring','Compress each spring with the specified compressor/adapter, seat both cotters and release the tool in control. Lightly tap the valve tip with a soft-face hammer to seat the cotters; excessive force can damage the valve. Inspect all eight cotters before continuing.',[233,234],'Four retained springs and eight seated cotters verified.',True,True),
step('lifters-install','Return pads and lifters','Oil pads and lifters with engine oil and return them to their original positions. Verify that each lifter rotates smoothly by finger. Remove the protective cloth and account for all tools. Final valve clearances are measured after cam/tensioner installation.',[234],'Four lifters smooth; pads matched; tools/cloth accounted for.',True,True)]
procedure('head-valve-inspect-reseal-bench-v1','Inspect valves and renew stem seals',valves,['Head removed and cams out; original valve positions identifiable.','Original-valve reuse path only; repair findings may require separate valve/guide/head service.'],['Serviceable original valves installed with new seals; cams and final clearance check remain.'],['14mm valve lapper90890-04101/YM-A8998','Spring compressor90890-04200/YM-04019;22mm adapter90890-04108/YM-04108','Guide bore gauge, stem micrometer, dial indicator/supports, contact-width measure','Soft-face hammer, clean labeled trays'],['Four new stem seals','Molybdenum-disulfide oil and engine oil','Blue layout fluid, clean test solvent','Exact replacement springs when required'],['Guide pressing/reaming and seat machining','Lapping original titanium valves','Whole-head replacement or cam clearance adjustment'],['engine','cylinder_head','valves'])
manifest()
